  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(value)

  def getOrElse(default: T): T = if (value == null) default else value

  def get: T = value
}

final class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get.apply(get))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList.filter(_.nonEmpty)
    val extracted = parts.foldLeft(Option(value)) { (currentOpt, part) =>
      currentOpt.flatMap { current =>
        current.asObject.flatMap(_.apply(part))
          .orElse {
            current.asArray.flatMap { arr =>
              if (part.forall(_.isDigit)) {
                val idx = part.toInt
                if (idx >= 0 && idx < arr.size) Some(arr(idx)) else None
              } else None
            }
          }
      }
    }

    extracted.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val cased = if (lowercase) stripped.toLowerCase(Locale.ROOT) else stripped

    if (cased.length < minLength) return None

    val trimmed = maxLength match {
      case Some(max) if cased.length > max => cased.take(max)
      case _ => cased
    }

    if (trimmed.isEmpty) None else Some(trimmed)
  }

  private def stripPunct(word: String): String = {
    val leadingStripped = word.dropWhile(punctuation.contains)
    leadingStripped.reverse.dropWhile(punctuation.contains).reverse
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    val result = ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      if (start >= 0) {
        val end = start + word.length
        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }
        currentPos = end
      }
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = ListBuffer.empty[String => String]
  private val validators = ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= entries
    this
  }

  def build(): T => Token = {
    val savedNormalizers = normalizers.toList
    val savedValidators = validators.toList
    val savedMetadata = metadata.toMap

    (value: T) => {
      savedValidators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      savedNormalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, savedMetadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
